	private void doRefresh(bool optionsChanged) {
		if (!isVisible()) {
			return;
		}

		ToolOptions fieldOptions = tool.getOptions(GhidraOptions.CATEGORY_BROWSER_FIELDS);
		ToolOptions opt = tool.getOptions(DecompilePlugin.OPTIONS_TITLE);

		// Current values of toggle buttons
		bool decompilerEliminatesUnreachable = decompilerOptions.isEliminateUnreachable();
		bool decompilerRespectsReadOnlyFlags = decompilerOptions.isRespectReadOnly();

		decompilerOptions.grabFromToolAndProgram(fieldOptions, opt, program);

		// If the tool options were not changed
		if (!optionsChanged) {
			// Keep these analysis options the same
			decompilerOptions.setEliminateUnreachable(decompilerEliminatesUnreachable);
			decompilerOptions.setRespectReadOnly(decompilerRespectsReadOnlyFlags);
		}
		else {
			// Otherwise, keep the new analysis options and update the state of the toggle buttons
			refreshToggleButtons();
		}

		controller.setOptions(decompilerOptions);

		if (currentLocation != null) {
			if (lockDisplay) {
				// Clear the cached results so the next time we come back to this function, it will
				// get re-decompiled.  If we don't do this, then we would need the ability to mark 
				// the cached results as needing update, so future loads of that cached function 
				// will trigger the refresh message.
				controller.clearCacheForCurrentFunction();
				setOverlayMessage(getOverlayRefreshMessage());
			}
			else {
				controller.refreshDisplay(program, currentLocation, null);
			}
		}
	}

	private string getOverlayRefreshMessage() {
		KeyStroke keyStroke = refreshAction.getKeyBinding();
		if (keyStroke != null) {
			string name = KeyBindingUtils.parseKeyStroke(keyStroke);
			return name + " to refresh";
		}
		return "Refresh needed";
	}

	private void updateOverlayMessage() {
		if (overlayPainter.isActive()) {
			setOverlayMessage(getOverlayRefreshMessage());
		}
	}

	private void setOverlayMessage(string s) {
		overlayPainter.setMessage(s);
		decorationPanel.repaint();
	}

	private void clearOverlayMessage() {
		overlayPainter.setMessage("");
		decorationPanel.repaint();
	}

	private void refreshToggleButtons() {
		displayUnreachableCodeToggle.setSelected(!decompilerOptions.isEliminateUnreachable());
		respectReadOnlyFlags.setSelected(!decompilerOptions.isRespectReadOnly());
	}

	private void doFollowUpWork() {
		if (isBusy()) {
			// try again later
			followUpWorkUpdater.updateLater();
			return;
		}

		Callback work = followUpWork.poll();
		while (work != null) {
			work.call();
			work = followUpWork.poll();
		}
	}

