	internal class _Anon_ServiceListener_1 : ServiceListener
	{


		/* @Override */
		public void serviceRemoved(Class<object> interfaceClass, object service) {
			if (interfaceClass.equals(typeof(GraphDisplayBroker))) {
				graphServiceRemoved();
			}
		}

		/* @Override */
		public void serviceAdded(Class<object> interfaceClass, object service) {
			if (interfaceClass.equals(typeof(GraphDisplayBroker))) {
				graphServiceAdded();
			}
		}
	
	}


